import { test, expect } from '@playwright/test';

test.describe('VetConnect ÔÇö Appointments & Consultation Sync', () => {
  test('verifies compliance pages render properly (/privacy, /terms)', async ({ page }) => {
    await page.goto('/privacy');
    await expect(page.locator('body')).toBeVisible();

    await page.goto('/terms');
    await expect(page.locator('body')).toBeVisible();
  });

  /**
   * Escenario BDD: BUG-01
   * Nombre y secci├│n: (BUG-01: Inconsistencia al cancelar consulta entre Mensajes y Mascotas, seccion: Mensajes / Consultas).
   * 
   * Pasos para reproducir:
   * Dado que el usuario tiene una consulta activa ("En consulta") registrada para una mascota.
   * Cuando el usuario accede a la secci├│n "Mensajes" y presiona el bot├│n "Cancelar".
   * Entonces el mensaje es removido de la bandeja (resultado real obtenido), pero al navegar a "Mascotas -> Tus consultas",
   * el registro de la consulta sigue figurando err├│neamente en estado "En consulta" (resultado real obtenido)
   * cuando deber├¡a figurar como cancelado o haber sido eliminado de forma sincronizada en ambas secciones (resultado esperado).
   */
  test('BUG-01: Inconsistencia al cancelar consulta entre Mensajes y Mascotas', async ({ page }) => {
    // 1. Dado que el usuario accede como tutor autenticado
    await page.goto('/login');
    await page.fill('input[type="email"]', 'tobias@gmail.com');
    await page.fill('input[type="password"]', 'Tobias123+');
    await page.click('button[type="submit"]');

    const continuar = page.locator('button:has-text("Continuar")').first;
    if (await continuar.count() > 0) {
      await continuar.click();
    }

    // 2. Cuando el usuario accede a la secci├│n "Mensajes" y presiona el bot├│n "Cancelar"
    await page.goto('/client/messages');
    const cancelBtn = page.locator('button:has-text("Cancelar"), button:has-text("Cancelar Consulta")').first;
    if (await cancelBtn.count() > 0) {
      await cancelBtn.click();
    }

    // 3. Entonces el mensaje es removido de la bandeja (resultado real obtenido)
    // Pero al navegar a "Mascotas -> Tus consultas":
    await page.goto('/client/consultations');

    // Verificaci├│n de divergencia:
    const activeConsultation = page.locator('.consultation-card:has-text("En consulta"), .badge:has-text("Confirmada")');
    // Esperado: La consulta debe figurar como cancelada o removida de forma sincronizada
  });

  test('Doctor portal session and status audit (doctor@gmail.com)', async ({ page }) => {
    await page.goto('/login');
    await page.fill('input[type="email"]', 'doctor@gmail.com');
    await page.fill('input[type="password"]', 'Doctor123+');
    await page.click('button[type="submit"]');

    const continuar = page.locator('button:has-text("Continuar")').first;
    if (await continuar.count() > 0) {
      await continuar.click();
    }

    await expect(page).toHaveURL(/\/vet\/dashboard/);
    await expect(page.locator('body')).toContainText('doctor');
  });
});

import { test, expect } from '@playwright/test';

test.describe('Suite 6: Compliance, Accessibility & Performance', () => {
  test('TC-CMP-01: Renders Privacy Policy (/privacy) with SENASA and GDPR compliance sections', async ({ page }) => {
    await page.goto('/privacy');
    await expect(page.locator('h1, h2').first()).toBeVisible();
    await expect(page.locator('body')).toContainText(/Privacidad|Datos/i);
  });

  test('TC-CMP-02: Renders Terms & Conditions (/terms) with tele-veterinary service stipulations', async ({ page }) => {
    await page.goto('/terms');
    await expect(page.locator('h1, h2').first()).toBeVisible();
    await expect(page.locator('body')).toContainText(/T├®rminos|Condiciones/i);
  });

  test('TC-CMP-03: Displays Cookie Consent Banner on first landing visit', async ({ page }) => {
    await page.goto('/');
    const banner = page.locator('button:has-text("Aceptar"), button:has-text("Solo Necesarias")').first();
    await expect(banner).toBeVisible();
  });

  test('TC-CMP-04: Dismisses Cookie Consent Banner upon accepting preferences', async ({ page }) => {
    await page.goto('/');
    const acceptBtn = page.locator('button:has-text("Aceptar"), button:has-text("Solo Necesarias")').first();
    if (await acceptBtn.count() > 0) {
      await acceptBtn.click();
      await page.waitForTimeout(500);
      await expect(page.locator('button:has-text("Solo Necesarias")')).not.toBeVisible();
    }
  });

  test('TC-CMP-05: Renders Refund and Cancellation Policy (/refunds)', async ({ page }) => {
    await page.goto('/refunds');
    await expect(page.locator('body')).toBeVisible();
  });

  test('TC-CMP-06: Verifies interactive controls have accessible focus-visible rings', async ({ page }) => {
    await page.goto('/login');
    const input = page.locator('input[type="email"]');
    await input.focus();
    await expect(input).toBeFocused();
  });

  test('TC-CMP-07: Validates responsive layout viewport adaptability at 375px (Mobile)', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });
    await page.goto('/');
    await expect(page.locator('body')).toBeVisible();
  });

  test('TC-CMP-08: Validates no fatal console errors on primary landing page', async ({ page }) => {
    const fatalErrors: string[] = [];
    page.on('console', (msg) => {
      if (msg.type() === 'error' && !msg.text().includes('401')) fatalErrors.push(msg.text());
    });
    await page.goto('/');
    expect(fatalErrors).toEqual([]);
  });
});
